<?php $this->layout('layouts/admin', ['title' => 'Thanh toán', 'pageTitle' => 'Quản lý thanh toán', 'activeMenu' => 'payment']) ?>
<?php $this->start('page') ?>
<div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Mã</th><th>Khách hàng</th><th>Tour</th><th>Phương thức</th><th>Mã giao dịch</th><th>Số tiền</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody><?php foreach($payments as $payment):?><tr><td>#<?= (int)$payment['paymentId'] ?></td><td><strong><?= $this->e($payment['customerName']) ?></strong><small class="d-block text-secondary"><?= $this->e($payment['customerEmail']) ?></small></td><td><?= $this->e($payment['tourTitle']) ?></td><td><?= $this->e($payment['paymentMethod']) ?></td><td class="font-monospace small"><?= $this->e($payment['transactionId'] ?: '—') ?></td><td class="fw-semibold"><?= number_format((float)$payment['amount'],0,',','.') ?>₫</td><td><span class="badge text-bg-<?= in_array($payment['status'], ['SUCCESS', 'COMPLETED'], true)?'success':($payment['status']==='PENDING'?'warning':'secondary') ?>"><?= $this->e(payment_status_label($payment['status'])) ?></span></td><td><div class="d-flex justify-content-end gap-1"><a href="/admin/payments/show/<?= (int)$payment['paymentId'] ?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-eye"></i></a><?php if($payment['status']==='PENDING'):?><form action="/admin/payments/confirm/<?= (int)$payment['paymentId'] ?>" method="POST" onsubmit="return confirm('Xác nhận đã nhận thanh toán?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-success"><i class="bi bi-check2-circle"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="8" class="text-center text-secondary py-5">Chưa có giao dịch.</td></tr><?php endif;?></tbody></table></div></div>
<?php $this->stop() ?>
